import{_ as r,a as l,b as o}from"./chunks/05fbdd4f8ff6bdfd0e03.BhVeEV1L.js";import{_ as a,C as i,o as s,c as n,j as e,a as h,E as c,a6 as m}from"./chunks/framework.CnPv4DE1.js";const w=JSON.parse('{"title":"用4个框架掌握说服力(并变得强大)","description":"","frontmatter":{"title":"用4个框架掌握说服力(并变得强大)","originalTitle":"Master Persuasion With 4 Frameworks (& Become Powerful)","date":"2024-08-29","originalUrl":"https://thedankoe.com/letters/the-greatest-skill-of-the-21st-century/","minutes":14,"sourceHash":"8dcd868353851028164b3243cdc7fb84d079dc25bd15a9ca1c8e126ddda77b79","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-greatest-skill-of-the-21st-century/"}]]},"headers":[],"relativePath":"letters/the-greatest-skill-of-the-21st-century.md","filePath":"letters/the-greatest-skill-of-the-21st-century.md"}'),f={name:"letters/the-greatest-skill-of-the-21st-century.md"};function u(d,p,g,b,k,_){const t=i("ArticleMeta");return s(),n("div",null,[p[0]||(p[0]=e("h1",{id:"用4个框架掌握说服力-并变得强大",tabindex:"-1"},[h("用4个框架掌握说服力(并变得强大) "),e("a",{class:"header-anchor",href:"#用4个框架掌握说服力-并变得强大","aria-label":'Permalink to "用4个框架掌握说服力(并变得强大)"'},"​")],-1)),c(t),p[1]||(p[1]=m('<p><a href="https://www.youtube.com/embed/2kOGHcN8Avs?si=pKf7BQfdL8kJfDCJ" target="_blank" rel="noreferrer">观看原文视频</a></p><p>说服力是21世纪最伟大的技能。</p><p>不,说服不是操纵。这是两个完全不同的词。</p><p>不,说服也不是不道德的。如果说服是不道德的,那你就是这个星球上最不道德的人,因为你每天都在说服别人,只不过你自己没意识到,而正是在这种无意识的情况下,它才会变成操纵。</p><p>当你试图说服朋友和你一起做某件事时,你正在使用说服力。</p><p>当你提出论据,说明为什么人们应该和你合作时,你正在使用说服力。</p><p>你正在努力从生活中得到你想要的东西。你在玩人生这场游戏。如果不是这样,你可能根本活不下去。你没有别的选择。</p><p>为了得到你想要的东西,你需要说服人们给你关注、资源、金钱,最重要的是……权力。</p><p>在这个社会里,唯一真正混得好、一直混得好的人,是那些拥有权力和影响力的人。</p><p>他们是那些努力获取实现目标所需资源、让自己变得有价值、并创造财富的人。</p><p>历史上从来没有哪个时代,软弱、平庸或不动脑子的人不被当作牛马对待。小心你的大脑现在就想劫持你的思想,让你成为那些没有过着你想要的生活的人灌输给你的观念的奴隶。</p><p>地位、权力和影响力本身并不坏。每个人都拥有它们。每个人都在争取它们。它们变成坏事,是当人们出于无意识的原因去追求它们的时候。也就是说,当你不理解你通过说服追求权力这件事,对大局产生的影响时。</p><p>这整篇文章可以完全是负面的,但如果它整体的故事线以及对你生活的影响是正面的,那它还算是件坏事吗?</p><p><strong>关于做出更好决策的一个小插曲:</strong> 你这一生中很可能要做一些别人会认为“不好”“肤浅”或“表面”的事情,因为他们看不到全局。他们看不到你所看到的东西。他们现在批评你,以后又会赞美你。如果你正在权衡是否该做某个决定,那就退后一步,试着想清楚它可能引发的所有可能情形。就像我之前说过的,某一只股票可以下跌,同时指数基金却在上涨。你可以吃一顿放纵餐,却依然保持健康。大多数人只会因为那顿放纵餐而变得神经质。而即便那个决定最终证明是个错误,朋友,欢迎来到人类的世界。那才是你下次能做出更好决策的唯一方式。犹豫不决、原地不动、不去追求更宏大的目标,才是所有“坏”决定中最坏的那个。</p><p>回到正题。</p><p>如果你想被视为有价值的人,你就需要产生权力。</p><p>如果你成功的策略是做个友善、高尚、有灵性的人,你就会被那些心机重的人挤到一边,而他们会比你产生更大的影响。</p><p>那些高举道德旗号说权力游戏是坏事的人,其实也在玩自己的权力游戏。一种自私的权力游戏。一种对人类毫无贡献的权力游戏。一种自我欺骗的游戏——什么都不做,只顾着布道说别人应该如何改变,借此分散他们照镜子看自己的注意力。</p><p>最近和你们很多人聊过之后,我把你们来到这里的原因归纳了一下。</p><p>你想要一份你喜欢的工作、一种有意义的生活方式,以及比市场上目前那些肤浅内容多一点点深度。</p><p>猜猜怎么着?</p><p>要实现这些目标中的任何一个,你都需要一定程度的权力。</p><p>你需要有人为你的工作付费。</p><p>你需要有人倾听你所说的话。</p><p>你需要对自己创造的生活方式拥有一种掌控感。</p><p>你需要说服的不仅仅是人,还有现实本身,让它为你的利益“合谋”。“创造”你理想的生活,就是在说服现实。你无法强迫现实。你无法欺骗现实。但你可以说服它。这正是真理的标志。</p><p>你内心其实早就知道,要得到你想要的东西,你需要学会说服。</p><p>唯一阻止你的,是那些自己人生没做出什么成绩的人的评判。</p><h2 id="如何-今天就开始说服" tabindex="-1">如何……今天就开始说服 <a class="header-anchor" href="#如何-今天就开始说服" aria-label="Permalink to &quot;如何……今天就开始说服&quot;">​</a></h2><p>结构化思维很重要。</p><p>提前处理一个反对意见:</p><p>不,框架和结构不会剥夺你的创造力。</p><p>每当我教写作框架、社媒帖子框架,或我如何写我的newsletter时,人们都会提出一些有道理的问题。</p><p>“如果我不想用框架呢?如果我想做真实的自己呢?如果我想写任何我想写的东西呢?”</p><p>(注意,我这里用“写作”来指代说服的方式,但你完全可以把它换成“说话”)。</p><p>我的回答是:</p><ul><li>去做吧。写你想写的东西。但在你真正理解是什么让写作产生影响力之前,先把你的写作组织进一个框架里。</li><li>框架不会伤害创造力。它们会增强创造力。你只有在拥有一个目标(有某个方向去为之创造)以及一些逼迫你发挥创造力的限制(比如一个框架)时,才能真正发挥创造力。在每天4小时内建立一份事业、而不牺牲你的健康和人际关系,比放弃生活中的一切去建立一份事业需要更多的创造力。</li><li>你其实已经在用一个框架了。它叫做你的思维,以及你被编程去思考问题的方式。问题在于,这个框架是无意识的,而且显然没什么效果,否则你早就拥有你想要的生活了。</li></ul><p>人类是通过故事来理解世界的。</p><p>他们把遇到的任何想法或信息,输入到大脑这台意义生成机器中,试图看看这些信息与自己的目标和过往经历有何关联。</p><p>所以,你<em>可以</em>写任何你想写的东西,但你写作或说服的目的是什么?</p><p>是得到你想要的东西。</p><p>换句话说,如果你的文字另一端没有一个具体的人,它又怎么能真正具有说服力呢?</p><p>你几乎在所有事情上都会用到下面这些方法。</p><p>我向你发起挑战:从今以后,在生活中的每一个场合都去<em>练习</em>说服,看看你的生活会发生怎样的变化。</p><ul><li>在你的社媒帖子、newsletter和落地页中</li><li>在你的人际交往、销售电话或私信中</li><li>在你的人际关系中做决定时</li><li>尤其是在你为自己的作品或产品做市场营销和推广时</li></ul><p>从今以后,要保持刻意和有意识。</p><p>抓住每一个机会去练习这些方法。</p><h3 id="金字塔原理" tabindex="-1">金字塔原理 <a class="header-anchor" href="#金字塔原理" aria-label="Permalink to &quot;金字塔原理&quot;">​</a></h3><p>金字塔原理是一种简单而有效的沟通方式。</p><p>你可以把它用在任何事情上。</p><p>具体做法如下:</p><ol><li>先给出你的答案、结论或核心观点</li><li>用3个以上的关键论点来证明你的结论</li><li>用事实、数据、轶事、引言等来支撑你的论点</li></ol><p>从宏观的角度来看,我所有的newsletter都是这样写出来的。</p><p>这是不是意味着,因为我没有随意混乱地写作,所以就显得我不够真实?还是说,这恰恰给了我一个能有效表达思想的载体?</p><p>你可以注意到,我常常一开始就抛出我想论证的观点。</p><p>然后,我会用newsletter中的几个部分来拆解支持这个观点的论据。</p><p>接着,我通常会用一些推文、引言或统计数据,让这些论据更有说服力。</p><p>我在<a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a>里有自己专门为此设计的模板。在写任何一篇newsletter之前,我会先写出我的观点、我的论据,以及写作过程中可以参考的研究资料。之后,那篇newsletter会被改写成一份YouTube脚本。等我们上线时,我会用Kortex模板更新<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>。</p><p>为什么金字塔原理有效?</p><p>读者能立刻知道这内容跟他们是否相关(钩子起作用了)。</p><p>他们能顺着你的逻辑,理解你是如何得出那个结论的。</p><p>最后,它简单易复制,可以用在任何地方。</p><p>表明你的观点,解释原因,并用事实支撑它。</p><h3 id="我自己使用的框架" tabindex="-1">我自己使用的框架 <a class="header-anchor" href="#我自己使用的框架" aria-label="Permalink to &quot;我自己使用的框架&quot;">​</a></h3><p>无论我写什么或谈什么话题,我都喜欢从一个痛点或问题开始。</p><p>这能让我后面的思路顺畅地展开。</p><p>它也能很好地为整个场景搭建框架,并对读者进行筛选。</p><p>当一个人意识到某个痛点时,他的大脑会把这个痛点和自己人生中的某个目标联系起来,从而激发进一步了解的欲望,同时也帮助他判断我写的内容是不是给他看的。然后,留下来的人会想要一个解决方案,如果我给出的方案足够好,他们就更有可能继续留下来,并投入到我进一步提供的价值中。</p><p>记住:人类是通过故事来理解世界的。故事通常从一个预示着某个“目标”或结果的问题开始。这会让读者的大脑开始主动填补这个故事的空白,并想继续读下去,看看自己猜的对不对。</p><p>下面给出几个可以尝试的框架,从简单开始,逐渐增加操作难度。</p><p>你可以把1和2用在社媒帖子上,或用作长文的开头。你可以把3用在newsletter、落地页,以及其他更长的对话场景中,比如销售电话。</p><p><strong>1) PP——痛点与流程(Pain &amp; Process)</strong></p><p>相当简单。</p><p>陈述痛点,并给出一个克服它的流程。</p><p>举一个推文的例子:</p><blockquote><p>如果你总是感到疲惫:</p><ul><li>别再半夜刷手机了</li><li>把你那糟糕的饮食习惯改一改</li><li>去散散步,动起来</li><li>培养一个让你痴迷的新兴趣</li></ul><p>你之所以感到疲惫,是因为你被困在了一个必然导致疲惫这一结果的日常routine里。</p></blockquote><p>聪明的做法是,把所有这些框架都用一个结论或行动号召来收尾。</p><p>另外,你的解决方案越独特,它产生的影响力就越大。</p><p>你是一个多巴胺贩子,所以要提供别人从未听过的新颖视角。这要求你必须对你所写的话题或市场有充分的阅读积累。如果你自己就是那个市场的一部分,这就会变得容易(*咳咳* <a href="/letters/how-to-create-your-niche-of-one-become-nicheless">You Are The Niche</a> *咳咳*)</p><p><strong>2) PAS(O)——问题、放大、解决方案、(优惠)(Problem, Amplify, Solution, Offer)</strong></p><p>这个框架也类似。</p><p>你从一个痛点开始,但这一次你要把它放大。</p><p>你要深入思考,这个痛点是如何蔓延到一个人生活的其他方面的。</p><p>比如疲惫会让你的丈夫/妻子觉得哪里出了问题,一些小矛盾也会莫名其妙地冒出来。或者,当你试图搭建副业时,你根本没法好好发挥(它到底能不能成)?又或者,下班回家后,你只想躺下吃点垃圾食品,而这显然对你毫无帮助。</p><p>你描述得越具体、越能让人产生共鸣就越好。在这种场景下,分享个人经历往往效果不错。所以,如果你自己经历过这个痛点,你可以谈谈它是如何影响<em>你</em>的生活的。</p><p>这个框架中的“优惠”部分是可选的。如果你只是用它来写一条社媒帖子,就不需要“优惠”这部分。如果你是用这个框架来做推广,那就把你的产品定位成针对你所锁定痛点的一种新颖解决方案。</p><p><strong>3) PASTOR——问题、放大、故事、见证、优惠、行动响应(Problem, Amplify, Story, Testimony, Offer, Response)</strong></p><p>同样,和前面的框架非常相似。</p><p>PASTOR框架篇幅稍长,最适合用在推广类材料上,比如落地页和邮件。</p><p>当你要推出一款产品、进行促销,或者已经很久没有推广过自己时,就用这个框架。</p><p>从问题开始。</p><p>把它放大。</p><p>讲述一个个人或客户的故事,说明他们<em>是如何</em>克服这个问题的。暗示你独特的解决方案。</p><p>通过他人的证言展示证据。如果你没有证言，试着通过个人成果或研究和数据来展示证据。</p><p>介绍你的产品的特性和好处，与你之前描述的痛点相对应。</p><p>让他们接下来采取行动，比如购买。</p><p><strong>4）试验各种框架</strong></p><p>学习说服力的最佳方法是：</p><ol><li>研究写作和演讲框架</li><li>把它们并排写下来</li><li>在现实世界中实践它们</li><li>注意它们之间的模式</li><li>打破规则</li></ol><p>框架、系统，以及大部分教育，都只是辅助轮。</p><p>大多数人在读这封信，或另一封信，或任何其他内容时，会看到有人提出了一个“新颖”的解决方案想去尝试。这可能是关系建议、健康习惯，或商业模式。</p><p>他们会采用一种策略，把它变成一种身份认同，最终在取得进步时意识到必须改变做事方式，从而受到伤害。</p><p>人们提供东西供人<em>测试</em>和<em>试验</em>，这是件很好的事。但当人们拿起这些东西，表现得好像它们是获得成果的唯一方式时，这就是件很糟糕的事。</p><p>所以，要学习说服力，就去研究并写下5到10个框架，在你的帖子、对话、通讯以及其他地方尝试它们。</p><p>然后，抛弃这些框架，运用最初让它们奏效的原理，随时成为一个有说服力的人。</p><p>我在<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>里教授我的APAG框架。这就是我如何写出这些长信，再转化成长视频（这让我脱颖而出）的方式。如果你愿意，可以试验一下这个框架。</p><h3 id="了解你在对谁说话" tabindex="-1">了解你在对谁说话 <a class="header-anchor" href="#了解你在对谁说话" aria-label="Permalink to &quot;了解你在对谁说话&quot;">​</a></h3><p>你的话只有在对方<em>感知</em>到它有价值时，才能说服他们。</p><p>如果你在谈论一个你很有见地的话题时说着高深莫测的行话，一个初学者不会在乎你说的话。他们很难产生共鸣或理解。</p><p>我们可以通过理解“5个意识层级”来解决这个问题：</p><ol><li><strong>无意识</strong> —— 没有意识到自己的问题以及它是如何伤害他们生活质量的。（专注于痛点。）</li><li><strong>问题意识</strong> —— 意识到自己的问题，但不知道如何解决。（专注于这些痛点的影响。）</li><li><strong>方案意识</strong> —— 意识到自己的问题，并知道有解决方案、教育或知识可以解决它。（专注于可操作的建议。）</li><li><strong>产品意识</strong> —— 意识到自己的问题，并知道有一套精简的路径或系统可以解决它。（专注于你独特的做事方式。）</li><li><strong>最高意识</strong> —— 他们已经准备好改变，只是需要一个正确的理由去行动。（专注于覆盖不同角度——用1000种不同方式说同一件事。）</li></ol><p>在我的通讯中，我经常试图把人们逐级提升。我假设人们对自己的问题一无所知，所以我在开头把它说出来。然后，我深入探讨这个问题及其对他们生活的影响。接着，我提出一步步的解决方案。在整封通讯中，我会推广我相关的产品或服务。</p><p>在类似社交帖子这样的内容中，我通常专注于第1到第3层级。</p><p>在社交推广中（在社交帖子之后），我专注于第4和第5层级。</p><p>从宏观角度看，我把我的社交帖子（漏斗顶端）当作让人们意识到问题的一种方式。我的通讯和产品则完成剩下的工作。</p><h2 id="我如何有说服力地写自己热爱的东西" tabindex="-1">我如何有说服力地写自己热爱的东西 <a class="header-anchor" href="#我如何有说服力地写自己热爱的东西" aria-label="Permalink to &quot;我如何有说服力地写自己热爱的东西&quot;">​</a></h2><p>我想展示一下我在Kortex里写出有影响力的内容的流程。</p><p>当然，你技术上可以用任何其他笔记或写作软件来做这件事，尤其是因为Kortex还没有正式发布（直到9月下旬才对<a href="https://kortex.co/" target="_blank" rel="noreferrer">候补名单上的人</a>开放）。</p><p>你知道，我们想创造一款真正能帮助人们更好地思考和写作的软件。大多数应用只是把你扔进一个令人困惑的环境里。你唯一的选择就是像往常一样做笔记——而我们都知道，你有多少想法就这样丢失了，或者变得不可理解。</p><p>要开始这个流程，我们需要四件东西：</p><ul><li><strong>一个要写的主题</strong> —— 最好是表现良好的东西。找一个在社交媒体上有效的主题，用这个流程让它变成你自己的。</li><li><strong>一个想法收集处</strong> —— 用来把你所有的想法都倒出来，并在新想法出现时随手记下来（你不会一次性拥有所有的想法）。</li><li><strong>一个大纲页面</strong> —— 用来以有说服力、有影响力、能吸引注意力的方式组织你所有的想法。（大部分写作工作在这里完成。）</li><li><strong>一个草稿页面</strong> —— 用来把你的想法和大纲串联起来。这不应该花很长时间，因为工作已经完成了。</li></ul><p>以下是我在Kortex中的写作流程：</p><p><img src="'+r+'" alt=""></p><p>我在每周开始时开始我的大纲。</p><p>我可以在手机上记录想法，并把它们附加到那个大纲上（想想你会如何在Todoist这样的应用里给一个项目添加“待办事项”）。</p><p>神奇之处发生在我的大纲里。</p><p>在上面截图的右上方框里，我们有一个叫“元素（Elements）”的功能。</p><p>这是一个简单的功能，也是我们的学员和用户最喜欢的一个。</p><p>简单来说，它们就是可以自定义命名的标注框，类似于Notion。但在Kortex里，你可以链接它们、镜像它们，最终还能为每个元素添加自定义提示词，让AI在几秒钟内为你创建大纲（基于你储存在第二大脑里的所有知识，所以这是独属于你写作方式的）。</p><p>以下是我带有“元素”的每周空白大纲的样子。</p><p><img src="'+l+'" alt=""></p><p>我在最上方为YouTube标题和标题头脑风暴各种“钩子”。</p><p>我把相关的笔记和想法连接起来，方便写作时导航。</p><p>我添加推文、引用和研究资料，以加强我的论点，给我提供论述要点。</p><p>（我把所有这些都存储在我的“资料库”中，它与Readwise集成，所以我可以保存从Kindle高亮到推文收藏到网页剪辑的一切内容。）</p><p><img src="'+o+'" alt=""></p><p>（你可以看到，我可以在左侧面板打开我的任何高亮、文档、捕捉、大纲等，把所有东西都放在写作时的同一个视图里——或者我也可以进入专注模式。）</p><p>然后，我列出要在写作中回答的问题或异议。</p><p>我描绘并放大痛点或问题。</p><p>我对目标或期望的结果进行头脑风暴。</p><p>我讲述我的经历以增加可信度，记录新颖的视角，创建可操作的步骤作为解决方案，总结大的想法，并对潜在的概念进行头脑风暴。</p><p>顺便说一下，这就是我想出所有最好的YouTube视频的方式。</p><p>我的视频《一人企业（如何把自己产品化）》其实就是我内容大纲里的“概念（流程）”元素。</p><p>这就是为什么大纲和元素如此重要。</p><p>你不是在学习如何有说服力地写作，你是在学习如何有说服力地组织你的想法，然后写作自然就变得容易了。</p><p>你可以用任何笔记应用创建这个系统，但可能会很困难，或者需要花很多时间。或者你得把5个应用串联起来用。</p><p>这并不是Kortex的唯一目的，因为我相信你能看出，这将延伸到日记、生产力和更多内容模板上。</p><p>而这仅仅是<a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a>的冰山一角。</p><p>所以，回顾一下你应该做什么来开始练习你的说服力：</p><ul><li>接受一个事实：你需要权力和地位，才能突破那个比你更有权力的人把你放进去的等级体系。</li><li>把金字塔原理作为起点。陈述你的观点，论证你的观点，支撑你的观点。</li><li>使用一种文案、内容或说服力框架来构建你的写作、演讲或视频脚本。</li><li>先基于那个框架创建一个大纲。</li><li>有一个地方来记录想法（因为最好的想法不会在你试图集中头脑风暴时全部出现）。</li><li>开始写你的草稿。把你大纲里的想法串联起来。</li></ul><p>然后，公开发布它，这样你才能开始获得数据。</p><p>如果人们不互动、不购买、不关注，那说明你哪里做错了，你可能需要在说服力之外多充实自己。</p><p>这里有几个可以开始的地方：</p><ul><li><a href="/letters/how-to-actually-grow-on-social-media-what-they-dont-tell-you">如何真正在社交媒体上成长</a></li><li><a href="https://theone-personbusiness.com/" target="_blank" rel="noreferrer">一人基础迷你课程</a></li><li><a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">数字经济学</a> 或我的<a href="https://thedankoe.com/" target="_blank" rel="noreferrer">其他课程</a></li></ul><p>这封信就到这里。</p><p>感谢阅读。</p><p>——Dan</p><hr><p><a href="/en/letters/the-greatest-skill-of-the-21st-century">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',159))])}const T=a(f,[["render",u]]);export{w as __pageData,T as default};
